'use strict';
// Main gallery, thumbnail and fullscreen image state are independent of cart variants.
const galleryState=new Map();let viewer=null;
const referenceImage=(folder,n,version)=>'https://gh.jumia.is/unsafe/fit-in/680x680/filters:fill(white)/product/'+folder+'/'+n+'.jpg?'+version;
const imageEntry=(src,label)=>({src:src.includes('gh.jumia.is')?src.replace('680x680','500x500'):src,full:src,thumb:src.replace(/(?:1600|680)x(?:1600|680)/,'150x150'),label});
const phone=getP('a07');phone.name='Samsung Galaxy A07 · 64GB, 4GB RAM';phone.specs.Storage='64GB';phone.variants=['Black'];phone.gallery=[1,2,3].map((n)=>imageEntry(referenceImage('49/6645003',n,'9574'),['Front and back','Display detail','Rear and side'][n-1]));phone.image=phone.gallery[0].src;
const shoes=getP('sneakers');shoes.name='Bekia Everyday Breathable Sneakers';shoes.brand='Bekia';shoes.specs.Color='Black';shoes.specs.Material='Polyester fabric';shoes.gallery=[1,2,3,4,5,6,7].map(n=>imageEntry(referenceImage('29/4950612',n,n===1||n===4?'9657':'4212'),'Product image '+n));shoes.image=shoes.gallery[0].src;shoes.variantStock={'EU 40':0,'EU 41':3,'EU 42':3,'EU 43':2,'EU 44':0};
for(const p of products){if(p.gallery)continue;const original=new URL(p.image);original.searchParams.set('w','1600');original.searchParams.set('q','90');const detail=new URL(original);detail.searchParams.set('fit','crop');detail.searchParams.set('h','1000');detail.searchParams.set('w','1000');detail.searchParams.set('crop','focalpoint');detail.searchParams.set('fp-x','.55');detail.searchParams.set('fp-y','.45');detail.searchParams.set('fp-z','1.7');p.gallery=[imageEntry(original.href,'Full product photo'),imageEntry(detail.href,'Cropped detail from the same photo')];}
function variantStock(p,v){return p.variantStock?.[v]??(p.unavailable?.includes(v)?0:p.stock)}
function currentGallery(p){const g=galleryState.get(p.id)||{index:0};g.index=Math.max(0,Math.min(g.index,p.gallery.length-1));galleryState.set(p.id,g);return g}
function galleryMarkup(p){const g=currentGallery(p);return '<section class="product-gallery" aria-label="Product image gallery"><div class="gallery-main"><button class="gallery-open" data-gallery="open" data-id="'+p.id+'" aria-label="Open fullscreen gallery, '+esc(p.gallery[g.index].label)+'"><img id="gallery-main-image" class="pdp-image" src="'+p.gallery[g.index].src+'" alt="'+esc(p.name+' — '+p.gallery[g.index].label)+'"><span class="gallery-expand">⤢ <span>Click to zoom</span></span></button><button class="gallery-prev" data-gallery="prev" data-id="'+p.id+'" aria-label="Previous image">‹</button><button class="gallery-next" data-gallery="next" data-id="'+p.id+'" aria-label="Next image">›</button><span class="gallery-count" id="gallery-count">'+(g.index+1)+' / '+p.gallery.length+'</span></div><div class="gallery-thumbnails" aria-label="Choose product image">'+thumbnailButtons(p,g.index,false)+'</div><p class="gallery-caption" id="gallery-caption" aria-live="polite">'+esc(p.gallery[g.index].label)+'</p><p class="variant-note" id="variant-gallery-note" aria-live="polite">Selected: '+esc(selectedVariant)+' · '+variantStock(p,selectedVariant)+' available</p></section>'}
function thumbnailButtons(p,index,full){return p.gallery.map((im,i)=>'<button class="gallery-thumb '+(index===i?'selected':'')+'" data-gallery="'+(full?'viewer-thumb':'thumb')+'" data-id="'+p.id+'" data-index="'+i+'" aria-label="Show image '+(i+1)+': '+esc(im.label)+'" aria-pressed="'+(index===i)+'"><img src="'+im.thumb+'" alt="" loading="lazy"></button>').join('')}
function selectImage(id,index){const p=getP(id),g=currentGallery(p);g.index=(index+p.gallery.length)%p.gallery.length;const img=$('#gallery-main-image');if(!img)return;img.src=p.gallery[g.index].src;img.alt=p.name+' — '+p.gallery[g.index].label;$('.gallery-open').setAttribute('aria-label','Open fullscreen gallery, '+p.gallery[g.index].label);$('#gallery-count').textContent=(g.index+1)+' / '+p.gallery.length;$('#gallery-caption').textContent=p.gallery[g.index].label;$$('.gallery-thumbnails .gallery-thumb').forEach((b,i)=>{b.classList.toggle('selected',i===g.index);b.setAttribute('aria-pressed',String(i===g.index))});}
function openViewer(id){const p=getP(id),g=currentGallery(p);viewer={id,index:g.index,scale:1,x:0,y:0,pointers:new Map(),start:null,pinch:null};modal('Product images','<div class="viewer-top"><span class="viewer-product">'+esc(p.name)+'</span><span id="viewer-counter" aria-live="polite"></span></div><div class="viewer-toolbar" aria-label="Image controls"><button data-gallery="zoom-out" aria-label="Zoom out">−</button><output id="viewer-zoom" aria-live="polite">100%</output><button data-gallery="zoom-in" aria-label="Zoom in">+</button><button data-gallery="reset" aria-label="Reset zoom">Reset</button><button data-gallery="fullscreen" aria-label="Toggle browser fullscreen">⤢</button></div><div class="viewer-stage" id="viewer-stage" tabindex="0" role="group" aria-label="Image canvas. Scroll to zoom, drag to pan, or use arrow keys to change images."><img id="viewer-image" alt="" draggable="false"><div class="viewer-load-error" hidden>Image could not load. <button data-gallery="retry">Retry</button></div></div><button class="viewer-arrow prev" data-gallery="viewer-prev" aria-label="Previous image">‹</button><button class="viewer-arrow next" data-gallery="viewer-next" aria-label="Next image">›</button><div class="viewer-bottom"><p id="viewer-caption" aria-live="polite"></p><div class="viewer-thumbnails">'+thumbnailButtons(p,g.index,true)+'</div><span class="viewer-help">Scroll or pinch to zoom · Drag to explore · ← → images · Esc close</span></div>');const d=$('#modal');d.classList.add('gallery-dialog');document.body.classList.add('viewer-open');$('#viewer-stage').focus();viewerImage();bindViewerGestures();}
function viewerImage(){const p=getP(viewer.id),img=$('#viewer-image');viewer.scale=1;viewer.x=viewer.y=0;const error=$('.viewer-load-error'),stage=$('#viewer-stage');error.hidden=true;stage.classList.add('loading');stage.setAttribute('aria-busy','true');img.onload=()=>{if(viewer){stage.classList.remove('loading');stage.setAttribute('aria-busy','false');error.hidden=true;clampPan();paintZoom()}};img.onerror=()=>{stage.classList.remove('loading');stage.setAttribute('aria-busy','false');error.hidden=false};img.src=p.gallery[viewer.index].full||p.gallery[viewer.index].src;img.alt=p.name+' — '+p.gallery[viewer.index].label;$('#viewer-counter').textContent=(viewer.index+1)+' / '+p.gallery.length;$('#viewer-caption').textContent=p.gallery[viewer.index].label;$$('.viewer-thumbnails .gallery-thumb').forEach((b,i)=>{b.classList.toggle('selected',i===viewer.index);b.setAttribute('aria-pressed',String(i===viewer.index))});const thumb=$('.viewer-thumbnails .selected');thumb?.scrollIntoView({block:'nearest',inline:'nearest'});paintZoom();}
function viewerChange(delta,index){if(!viewer)return;const p=getP(viewer.id);viewer.index=index??(viewer.index+delta+p.gallery.length)%p.gallery.length;galleryState.set(p.id,{index:viewer.index});selectImage(p.id,viewer.index);viewerImage();}
function clampPan(){if(!viewer)return;const stage=$('#viewer-stage'),img=$('#viewer-image');const maxX=Math.max(0,(img.clientWidth*viewer.scale-stage.clientWidth)/2),maxY=Math.max(0,(img.clientHeight*viewer.scale-stage.clientHeight)/2);viewer.x=Math.max(-maxX,Math.min(maxX,viewer.x));viewer.y=Math.max(-maxY,Math.min(maxY,viewer.y));}
function paintZoom(){if(!viewer)return;clampPan();$('#viewer-image').style.transform='translate('+viewer.x+'px,'+viewer.y+'px) scale('+viewer.scale+')';$('#viewer-zoom').textContent=Math.round(viewer.scale*100)+'%';$('#viewer-stage').classList.toggle('zoomed',viewer.scale>1);$('[data-gallery="zoom-out"]').disabled=viewer.scale<=1;$('[data-gallery="zoom-in"]').disabled=viewer.scale>=4;}
function zoomTo(scale){if(!viewer)return;viewer.scale=Math.max(1,Math.min(4,scale));if(viewer.scale===1)viewer.x=viewer.y=0;paintZoom()}
function bindViewerGestures(){const stage=$('#viewer-stage');stage.addEventListener('wheel',e=>{e.preventDefault();zoomTo(viewer.scale*(e.deltaY<0?1.15:1/1.15))},{passive:false});stage.addEventListener('dblclick',()=>zoomTo(viewer.scale>1?1:2));stage.addEventListener('pointerdown',e=>{if(!viewer)return;stage.setPointerCapture(e.pointerId);viewer.pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});viewer.start={x:e.clientX,y:e.clientY,panX:viewer.x,panY:viewer.y,time:Date.now()};if(viewer.pointers.size===2){const [a,b]=[...viewer.pointers.values()];viewer.pinch={distance:Math.hypot(a.x-b.x,a.y-b.y),scale:viewer.scale}}});stage.addEventListener('pointermove',e=>{if(!viewer?.pointers.has(e.pointerId))return;viewer.pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(viewer.pointers.size===2){const [a,b]=[...viewer.pointers.values()];if(viewer.pinch?.distance)zoomTo(viewer.pinch.scale*Math.hypot(a.x-b.x,a.y-b.y)/viewer.pinch.distance)}else if(viewer.scale>1&&viewer.start){viewer.x=viewer.start.panX+e.clientX-viewer.start.x;viewer.y=viewer.start.panY+e.clientY-viewer.start.y;paintZoom()}});const end=e=>{if(!viewer)return;const start=viewer.start,pinch=viewer.pinch;viewer.pointers.delete(e.pointerId);if(!viewer.pointers.size){if(!pinch&&viewer.scale===1&&start&&Math.abs(e.clientX-start.x)>50&&Math.abs(e.clientY-start.y)<80)viewerChange(e.clientX<start.x?1:-1);viewer.start=null;viewer.pinch=null}else if(viewer.pointers.size===1){const p=[...viewer.pointers.values()][0];viewer.start={x:p.x,y:p.y,panX:viewer.x,panY:viewer.y}}};stage.addEventListener('pointerup',end);stage.addEventListener('pointercancel',()=>{if(viewer){viewer.pointers.clear();viewer.start=viewer.pinch=null}});}
$('#modal').addEventListener('keydown',e=>{if(!viewer)return;const actions={ArrowRight:()=>viewerChange(1),ArrowLeft:()=>viewerChange(-1),'+':()=>zoomTo(viewer.scale+.5),'=':()=>zoomTo(viewer.scale+.5),'-':()=>zoomTo(viewer.scale-.5),'0':()=>zoomTo(1),Home:()=>viewerChange(0,0),End:()=>viewerChange(0,getP(viewer.id).gallery.length-1)};if(actions[e.key]){e.preventDefault();actions[e.key]()}});
$('#modal').addEventListener('close',()=>{if(!viewer)return;viewer=null;$('#modal').classList.remove('gallery-dialog');document.body.classList.remove('viewer-open');if(document.fullscreenElement===$('#modal'))document.exitFullscreen?.().catch(()=>{});});
window.addEventListener('resize',()=>viewer&&paintZoom());
document.addEventListener('click',async e=>{const b=e.target.closest('[data-gallery]');if(b){e.preventDefault();e.stopImmediatePropagation();const id=b.dataset.id,p=getP(id),g=p?currentGallery(p):null;switch(b.dataset.gallery){case'open':openViewer(id);break;case'prev':selectImage(id,g.index-1);break;case'next':selectImage(id,g.index+1);break;case'thumb':selectImage(id,Number(b.dataset.index));break;case'viewer-prev':viewerChange(-1);break;case'viewer-next':viewerChange(1);break;case'viewer-thumb':viewerChange(0,Number(b.dataset.index));break;case'zoom-in':zoomTo(viewer.scale+.5);break;case'zoom-out':zoomTo(viewer.scale-.5);break;case'reset':zoomTo(1);break;case'retry':{const img=$('#viewer-image');img.src=getP(viewer.id).gallery[viewer.index].full||getP(viewer.id).gallery[viewer.index].src;break}case'fullscreen':try{if(document.fullscreenElement)await document.exitFullscreen();else await $('#modal').requestFullscreen()}catch{toast('The viewer already fills this browser window.')}break;}return}const v=e.target.closest('[data-action="variant"]');if(v&&!v.disabled){e.preventDefault();e.stopImmediatePropagation();selectedVariant=v.dataset.value;$$('.variant').forEach(b=>b.classList.toggle('active',b===v));const p=getP(route().path.split('/')[2]);$('#variant-gallery-note').textContent='Selected: '+selectedVariant+' · '+variantStock(p,selectedVariant)+' available';if(p.variantImages?.[selectedVariant])selectImage(p.id,p.variantImages[selectedVariant]);}},true);
render();
